// src/lib/game/bot-kind.ts
var botKinds = ["bot", "mm", "money", "engine", "classic-engine"];
var botLabels = { bot: "Bot", mm: "MM (Minh / Melia)", money: "Money", engine: "Engine (current)", "classic-engine": "Engine (historical v4)" };
var isBotKind = (value) => botKinds.includes(value);
function resolveBotKind(kind, leader) {
  if (kind !== "bot")
    return kind;
  switch (leader) {
    case "melia":
    case "nereon":
      return "rl";
    case "thaleia":
    case "doreios":
      return "rl";
    default:
      throw new Error(`Unknown bot leader: ${leader}`);
  }
}

